7	/**
8	 * Normalizes the optional owner email. Email is optional, so a null or blank value is
9	 * left untouched; when present it must be a syntactically valid address (otherwise a
10	 * 400 via {@link InvalidEmailException}) and is stored lower-cased. Mutates the
11	 * published {@link OwnerFieldsDto} in place so the owner is built and saved with the
12	 * normalized value.
13	 */
14	public class NormalizeOwnerEmail {
15	
16	    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
17	        String email = request.getEmail();
18	        if (email == null || email.isBlank()) {
19	            return;
20	        }
21	        if (!EmailNormalizer.isValid(email)) {
22	            throw new InvalidEmailException(email);
23	        }
24	        request.setEmail(EmailNormalizer.normalize(email));
25	    }
26	}
