7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
8	
9	/**
10	 * Rejects a create request whose telephone is already used by an existing owner. Runs
11	 * after {@link NormalizeOwnerTelephone} (so the request telephone is the E.164 value)
12	 * and before {@link BuildOwner}, so a collision is a 409 via
13	 * {@link DuplicateTelephoneException} before any owner is built or saved. Each stored
14	 * telephone is normalized to E.164 the same way before comparing.
15	 */
16	public class EnsureUniqueTelephone {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateTelephoneException {
20	        String telephone = request.getTelephone();
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (telephone.equals(TelephoneNormalizer.toE164(existing.getTelephone()))) {
23	                throw new DuplicateTelephoneException(telephone);
24	            }
25	        }
26	    }
27	}
