1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
10	
11	/**
12	 * Rejects a create request whose last name and address already belong to an existing
13	 * owner, comparing both case-insensitively with collapsed whitespace. Runs before
14	 * {@link BuildOwner}, so a collision is a 409 via {@link DuplicateHouseholdException}
15	 * before any owner is built or saved. A request that opts in with
16	 * {@code sharesHousehold=true} is allowed through, since the owners knowingly share a
17	 * household.
18	 */
19	public class EnsureUniqueHousehold {
20	
21	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
22	            throws DuplicateHouseholdException {
23	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
24	            return;
25	        }
26	        String lastName = normalize(request.getLastName());
27	        String address = normalize(request.getAddress());
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (lastName.equals(normalize(existing.getLastName()))
30	                    && address.equals(normalize(existing.getAddress()))) {
31	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
32	            }
33	        }
34	    }
35	
36	    /** Case-fold and collapse whitespace so trivial spacing/casing differences still match. */
37	    private static String normalize(String value) {
38	        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
39	    }
